/**
 * Shared helpers for the fetch-based forms across the app.
 *
 * Every form submits via fetch() and displays the server's response body
 * inline on failure. Most of our own error responses are short plain-text
 * strings, which display nicely - but some failures are generated by
 * Flask/Werkzeug (or a proxy in front of the app) and come back as a full
 * HTML error page. Dumping that into a banner shows the user raw markup.
 *
 * cleanErrorText() is the guard: it passes through short plain-text
 * messages unchanged, and replaces anything that looks like an HTML
 * document with a readable fallback.
 */

function cleanErrorText(text, fallback) {
    fallback = fallback || "Something went wrong. Please try again.";

    if (!text) return fallback;

    const trimmed = text.trim();
    if (!trimmed) return fallback;

    // Anything that looks like a full HTML document (Flask/Werkzeug error
    // pages, proxy error pages) is not fit to show directly.
    const looksLikeHtml = /^<!doctype/i.test(trimmed) || /^<html/i.test(trimmed) || /<\/?(html|body|title|h1)\b/i.test(trimmed);
    if (looksLikeHtml) {
        // Werkzeug puts the useful sentence in <p>...</p> - use it if we can
        // find one, otherwise fall back to the caller's generic message.
        const p = trimmed.match(/<p>(.*?)<\/p>/is);
        if (p) {
            const inner = p[1].replace(/<[^>]*>/g, "").trim();
            if (inner && inner.length < 200) return inner;
        }
        return fallback;
    }

    // Guard against anything unexpectedly long ending up in a small banner.
    if (trimmed.length > 300) return fallback;

    return trimmed;
}
